          "q_ta": "விழாவின் நுழைவுக் கட்டணம் எவ்வளவு?",
          "q_ko": "축제의 입장료는 얼마입니까?",
          "q_es": "¿Cuánto cuesta la entrada al festival?",
          "q_kn": "ಉತ್ಸವದ ಪ್ರವೇಶ ಶುಲ್ಕ ಎಷ್ಟು?",
          "q_ml": "ഉത്സവത്തിന്റെ പ്രവേശന ഫീസ് എത്രയാണ്?",
