          "q_kn": "ಸಾರ್ವಜನಿಕ ಸಾರಿಗೆಯನ್ನು ಬಳಸಲು ಏಕೆ ಸೂಚಿಸುತ್ತಿದ್ದಾರೆ?",
          "q_ml": "പൊതുഗതാഗതം ഉപയോഗിക്കാൻ നിർദ്ദേശിക്കുന്നത് എന്തുകൊണ്ട്?",
