      "transcript_kn": "ಮರು ಓದಿನ ಆನಂದ: ಓದಿದ ಪುಸ್ತಕವನ್ನೇ ಮತ್ತೆ ಓದುವುದೇಕೆ? ನಮ್ಮ ಅನುಭವ ಬೆಳೆದಂತೆ ಅದೇ ಪುಸ್ತಕ ಹೊಸ ಅರ್ಥ ನೀಡುತ್ತದೆ. ಶ್ರೇಷ್ಠ ಪುಸ್ತಕವು ನಮ್ಮ ಬದುಕಿನೊಂದಿಗೆ ಬೆಳೆಯುವ ಕನ್ನಡಿಯಾಗಿದೆ.",
