      "transcript_te": "'ఫలితాలను' కొలవడం: సంఖ్యాపరమైన లక్ష్యాలను మాత్రమే కొలమానంగా తీసుకుంటే, సంఖ్యలలో కనిపించని సహాయ సహకారాలు, సంస్థాగత సంస్కృతి వంటి అత్యంత విలువైన అంశాలు విస్మరించబడతాయి.",
