      "transcript_kn": "ಮುಟ್ಟದ ಪ್ರಕೃತಿಯೆಂಬ ಭ್ರಮೆ: ಮಾನವನ ಸಂಪರ್ಕವಿಲ್ಲದ ಪ್ರಕೃತಿಯೇ ಶ್ರೇಷ್ಠವೆಂಬುದು ಸುಳ್ಳು. ಶತಮಾನಗಳ ಕಾಲ ಮಾನವನ ಸಮತೋಲಿತ ಸಹಬಾಳ್ವೆಯಿಂದಲೇ ಜೀವವೈವಿಧ್ಯ ಉಳಿದುಕೊಂಡಿದೆ.",
