      "transcript_kn": "ಹಬ್ಬಗಳು ಮರೆಯಾದಾಗ: ಸಾಂಪ್ರದಾಯಿಕ ಜಾತ್ರೆಗಳು ಕೇವಲ ಮನರಂಜನೆಯಲ್ಲ; ಅವು ಸಮಾಜದ ಐಕ್ಯತೆ ಮತ್ತು ಪರಸ್ಪರ ನಂಬಿಕೆಯನ್ನು ಕಾಪಾಡುವ ಬೇರುಗಳು. ಅವು ನಿಂತರೆ ಸಮಾಜ ಛಿದ್ರವಾಗುತ್ತದೆ.",
