          "q_hi": "अर्थशास्त्री द्वारा प्रस्तावित श्रम सुधारों में क्या शामिल है?",
          "q_ta": "பொருளாதார நிபுணர் முன்மொழியும் சீர்திருத்தங்களில் அடங்குவது எது?",
          "q_ko": "이코노미스트가 제안하는 노동시장 구조개혁에 포함되는 것은 무엇입니까?",
